  1	//predicate for primeness
  2	ghost predicate prime(n: nat)
  3	
  4	{ n > 1 && (forall nr | 1 < nr < n :: n % nr != 0) }
  5	
  6	datatype Answer = Yes | No | Unknown
  7	
  8	//the class containing a prime database, if a number is prime it returns Yes, if it is not No and if the number
  9	//is not in the database it returns Unknown
 10	class {:autocontracts} PrimeMap{
 11	
 12	  var database: map<nat, bool>; 
 13	
 14	//the valid invariant of the class
 15	  ghost predicate Valid()
 16	    reads this
 17	  {
 18	    forall i | i in database.Keys :: (database[i] == true <==> prime(i)) 
 19	  }
 20	
 21	//the constructor
 22	  constructor()
 23	    ensures database == map[]
 24	  {
 25	    database := map[];
 26	  }
 27	
 28	  // insert an already known prime number into the database
 29	  method InsertPrime(n: nat)
 30	    modifies this;
 31	    ensures database.Keys == old(database.Keys) + {n}
 32	    ensures database == database[n := true] 
 33	  {
 34	    database := database[n := true];
 35	  }
 36	
 37	  // check the primeness of n and insert it accordingly into the database 
 38	  method InsertNumber(n: nat) 
 39	    modifies this
 40	    ensures database.Keys == old(database.Keys) + {n}
 41	    ensures prime(n) <==> database == database[n := true] 
 42	    ensures !prime(n) <==> database == database[n := false] 
 43	  {
 44	    var prime : bool;
 45	    prime := testPrimeness(n);
 46	    database := database[n := prime];
 47	  }
 48	
 49	  // lookup n in the database and reply with Yes or No if it's in the database and it is or it is not prime,
 50	  // or with Unknown when it's not in the databse
 51	  method IsPrime?(n: nat) returns (answer: Answer) 
 52	      ensures database.Keys == old(database.Keys)
 53	      ensures (n in database) && prime(n) <==> answer == Yes 
 54	      ensures (n in database) && !prime(n) <==> answer == No 
 55	      ensures !(n in database) <==> answer == Unknown
 56	  {
 57	    if !(n in database){
 58	      return Unknown;
 59	    } else if database[n] == true {
 60	      return Yes;
 61	    } else if database[n] == false {
 62	      return No;
 63	    }
 64	  }
 65	
 66	  // method to test whether a number is prime, returns bool
 67	  method testPrimeness(n: nat) returns (result: bool) 
 68	      requires n >= 0
 69	      ensures result <==> prime(n)
 70	  {
 71	   if n == 0 || n == 1{
 72	    return false;
 73	   }
 74	    var i := 2;
 75	    result := true;
 76	
 77	    while i < n 
 78	      invariant i >= 2 && i <= n
 79	      invariant result <==> (forall j |  1 < j <= i - 1 :: n % j != 0)
 80	    {
 81	      if n % i == 0 {
 82	        result := false; 
 83	      }
 84	      i := i + 1;
 85	    }
 86	  }
 87	}
 88	
 89	method testingMethod() {
 90	
 91	  // witness to prove to dafny (exists nr | 1 < nr < n :: n % nr != 0), since 
 92	  // the !(forall nr | 1 < nr < n :: n % nr != 0) from !prime predicate ==>  (exists nr | 1 < nr < n :: n % nr == 0)
 93	  assert !(forall nr | 1 < nr < 15 :: 15 % nr != 0) ==>  (exists nr | 1 < nr < 15 :: 15 % nr == 0);
 94	  assert 15 % 3 == 0;
 95	  assert(exists nr | 1 < nr < 15 :: 15 % nr == 0);
 96	
 97	  var pm := new PrimeMap();
 98	
 99	  // InsertPrime test
100	  pm.InsertPrime(13);
101	  // InsertNumber test
102	  pm.InsertNumber(17);
103	  pm.InsertNumber(15);
104	
105	  assert pm.database.Keys == {17, 15, 13};
106	
107	  var result: Answer := pm.IsPrime?(17);
108	  assert result == Yes;
109	
110	  var result2: Answer := pm.IsPrime?(15);
111	  assert result2 == No;
112	
113	  var result3: Answer := pm.IsPrime?(454);
114	  assert result3 == Unknown;
115	
116	  var result4: Answer := pm.IsPrime?(13);
117	  assert result4 == Yes;
118	
119	}
120	
121	
122	
123	
